__device__ __forceinline__ int warp_claim(int* cursor, int lane) {
    int task = lane == 0 ? atomicAdd(cursor, 1) : 0;
    return __shfl_sync(0xffffffffu, task, 0);
}

__device__ __forceinline__ void dispatch_one(const Params* params, int token,
                                              int lane) {
    int destinations[K];
    int payload_slots[K];
    for (int route = 0; route < K; ++route) {
        const int expert = params->expert_ids[token * K + route];
        const int destination = expert / (E / R);
        Mailbox* remote = params->mailboxes[destination];
        int payload_slot = -1;
        if (destination != params->rank) {
            for (int prior = 0; prior < route; ++prior)
                if (destinations[prior] == destination)
                    payload_slot = payload_slots[prior];
            if (payload_slot < 0) {
                // CAKE_EFFECT: payload.reserve
                payload_slot = lane == 0 ? sys_add_relaxed(&remote->payload_tail, 1) : 0;
                payload_slot = __shfl_sync(0xffffffffu, payload_slot, 0);
