        __syncwarp();
    }
    if (lane == 0) {
        const int old = sys_add_acq_rel(
            &params->mailboxes[params->rank]->dispatch_completed, 1);
        if (old == T - 1)
            for (int peer = 0; peer < R; ++peer)
                sys_add_release(&params->mailboxes[peer]->dispatch_sources_done, 1);
    }
