            int permit = 0;
            if (lane == 0) {
                stop = sys_load_acquire(&local->chunk_completed[0]) >=
                       cake_weave::chunk_size<T>(0, params->chunks) * K ||
                       atomicAdd(&local->stolen, 0) >= params->steal_budget ||
                       no_more_inbound(local);
